import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"8、【比】 坤下坎上","description":"周易尚氏學 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"周易尚氏學 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"classics/shangshi/013.md","filePath":"classics/shangshi/013.md"}'),s={name:"classics/shangshi/013.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>比親也。輔也。坎坤同舍於子。故曰比。唐以前。先天象失傳。故卦名不得解。清毛大可黃宗義等知之而之認。後學不察。相率以言先天為戒。而自命為漢易。豈知康成注月令。於季夏雲。未屬巽辰。又在巽位。巽若不在西南。未能在巽位乎。是先天方位。鄭且明言之。九家注同人雲。乾舍於離。與日同居。荀爽注同人雲。乾舍於離。相與同居。注陰陽之義配日月雲。乾舍於離。配日而居。坤舍於坎。配月而居。已一再言之乎。比之義即以坎坤同居也。原者田也。左傳僖二十八年。原田每每。注高平曰原。周禮太卜原兆注。原原田也。按古皆井田。每每者。井與井相間之形。坤為拆。象原田。故曰原筮。坎為筮。坤為原。原筮。猶言野筮也。曲禮雲。外事以剛日。鄭注。外事郊外之事。儀禮士喪禮。筮於兆域。兆域在郊外。即原筮也。而乾寶因周禮三卜。一曰原兆。即訓原為卜。可謂大謬。按周禮。太卜掌三兆之法。一曰玉兆。二曰瓦兆。三日原兆。注。言龜兆似玉瓦原之璺鏬。然則原者原田。田必有璺鏬。象龜兆之形。故曰原兆。豈以原為卜乎。故原指坤。於訓卜固非。孔穎達謂原為原究。朱子謂原為再。王夫之謂原為本。俞樾謂原為始。為本。益浮泛不切。故夫說易而不求象。未有能當者也。元謂九五。永貞者永定也。坤為亂。故曰不寧。方。詩小雅方舟為梁。漢書韓信傳雲。今井陘之道。車不得方軌。注皆訓方為並。方來。謂下四陰並來歸五也。舊解不求卦象。訓方為將。為四方。皆失之。艮為夫。上六獨居艮後。故曰後夫。下四陰皆承陽。獨上六乘陽不順。故兇。此卦因原象筮象夫象失傳。故自漢迄今。無得解者。</p><p>彖曰。比。吉也。比。輔也。下順從也。原筮元永貞無咎。以剛中也。不寧方來。上下應也。後夫兇。其道窮也。</p><p>上謂五。下謂四陰。上六居卦之極。故曰道窮。</p><p>象曰。地上有水。比。先王以建萬國。親諸侯。</p><p>先王謂五。坤為萬國。國必建侯。坤多故曰諸侯。五南面稱尊。撫臨天下。故王者取以為法。親即比也。</p><p>初六。有孚比之。無咎。有孚盈缶。終來有它。吉。</p><p>坎為孚。五為卦主。故亦孚於初而比之。初失位。本有咎。比五故無咎。坤為缶。初居缶之最下。去五雖遠。然坎雨下注。始於四。以次及初。至初而缶盈矣。故曰有孚盈缶。陽性上升。五升上剝。剝窮上反下。則初陽復矣。故曰來。以其有待。故曰終來。有它謂有應於他方也。大過九四曰有它吝。謂應初也。中孚初九曰有它不燕。謂應四也。此兩卦皆有應。而皆不吉者。以得敵為害也。故不安。故吝。此曰有它吉者。以陽來反初。當位有應。故吉。荀爽以非應釋有它，清易家多從之。豈知大過中孚皆有應。而亦曰有它。則夫有它之不指非應甚明。虞翻謂初動成屯得正故吉。豈知此謂之變。不謂之來。更不得謂之終來。曰終來。固確有所指。且果如虞說。初動之正。乃初爻自變。益不得謂之有它。理甚明矣。虞亦知其說之有鏬。復申曰在內稱來。夫爻在外曰往。在內曰來。如需訟之往來得中。否泰之大小往來。皆是。茲曰終來。若僅在內稱來。復何有始終之可言乎。失經旨矣。它古蛇字。易林以坤為它。損之比雲。大它當路。使季畏懼。以比下坤為它。不讀為誰他之他。繫辭雲。龍它之蟄。以存身也。龍為乾。它為坤。言蟄於戍亥也。林所本也。而巽亦為蛇。故大過九四。中孚初九。亦曰有它。後儒頗有用焦說者又一義也。</p><h3 id="象曰。比之初六。有它吉也。" tabindex="-1">象曰。比之初六。有它吉也。 <a class="header-anchor" href="#象曰。比之初六。有它吉也。" aria-label="Permalink to “象曰。比之初六。有它吉也。”">​</a></h3><p>六二。比之自內。貞吉。</p><p>二應五。故曰自內。言自內比五也。二當位中正。故曰貞吉。</p><h3 id="象曰。比之自內。不自失也。" tabindex="-1">象曰。比之自內。不自失也。 <a class="header-anchor" href="#象曰。比之自內。不自失也。" aria-label="Permalink to “象曰。比之自內。不自失也。”">​</a></h3><p>言自內比五。不敢安逸也。失通佚。諸家作得失詁。非。</p><p>六三。比之匪人。</p><p>虞氏逸象乾為人。六三不當位無應。承乘皆陰。行失類。故曰比之匪人。言不得陽也。</p><h3 id="象曰。比之匪人。不亦傷乎。" tabindex="-1">象曰。比之匪人。不亦傷乎。 <a class="header-anchor" href="#象曰。比之匪人。不亦傷乎。" aria-label="Permalink to “象曰。比之匪人。不亦傷乎。”">​</a></h3><p>三獨失實。故可傷。</p><p>六四。外比之貞吉。</p><p>四承五。外比即從上。貞吉者。卜問則吉也。</p><h3 id="象曰。外比於賢。" tabindex="-1">象曰。外比於賢。 <a class="header-anchor" href="#象曰。外比於賢。" aria-label="Permalink to “象曰。外比於賢。”">​</a></h3><p>以從上也。陽為賢指五。</p><p>九五。顯比。王用三驅。失前禽。邑人不誡。吉。</p><p>九五伏離。當陽得位。嚮明而治。故曰顯比。王謂五。三驅獵禮也。漢書五行志。田狩有三驅之制。注。三驅之禮。一為乾豆。二為賓客。三為君庖。又晉書五行志。登車有三驅之制。又劉聰傳。校獵上林。將軍負戟前導。行三驅之禮。艮數三。故曰三驅。前禽謂下四陰。上為後。故知前為下。失逸古通。逸前禽者。喻人皆來比。無所誅殺。任其逸也。坤為邑。不誡謂王師寬大。所至之邑。百姓仍安居樂業。人人親附。不驚誡也。說文誡敕也。廣韻言警也。左傳桓十一年。鄖人軍其郊。必不誡。言無備虞也。</p><h3 id="象曰。顯比之吉。位正中也。舍逆取順。失前禽也。邑人不誡。上使中也。" tabindex="-1">象曰。顯比之吉。位正中也。舍逆取順。失前禽也。邑人不誡。上使中也。 <a class="header-anchor" href="#象曰。顯比之吉。位正中也。舍逆取順。失前禽也。邑人不誡。上使中也。" aria-label="Permalink to “象曰。顯比之吉。位正中也。舍逆取順。失前禽也。邑人不誡。上使中也。”">​</a></h3><p>九五中正。故顯。逆迎也。下四陰皆逆我者也。逆而來歸。理應舍之。故曰逸前禽。如紂師之倒戈歸周是也。王注禽順行揹我而走者。則射而取之。按順行與我同向。同向即揹我。上六是也。故取之。此四字只王注得解。虞翻謂舍逆指上六。前禽指初。豈知後夫如得舍。尚何雲兇。初有孚盈缶。即孚於五。又安得獨不及初。而後儒皆從之。異已。上使中者。言五所遣師徒。合乎中道。故無過舉。得不誡也。唐郭京舉正。稱得輔嗣真本。以舍逆取順。在失前禽下。朱芹引李清植曰。考象傳。屢以禽與東部字韻。屯三爻禽與窮韻。恆四爻禽與容韻。此又與中韻。郭京所改。顯失易韻。今按詩小雅呦呦鹿鳴。食野之芩。韻與此同。焦氏易林用韻如此者尤多。而履之夬以禽與功韻。與象傳尤符。蓋古音原如此。今晉人讀禽為輕。正與古音合。郭京所稱輔嗣本。無論真偽。不可從也。</p><p>上六。比之無首。兇。</p><p>坎為首。首謂五也。而五為坎主。上六乘陽。首為所蔽。故曰無首。大過上六曰滅頂兇。既濟上六曰。濡其首。與此義同也。而復於此爻。更曰反君道。無首即反君道。反君故兇。荀虞皆不知首指五。故說皆不切。清惠士奇更實指曰首指上。謂木一在下為本。一在上為末。末即首。意謂上六為末爻。故為首也。說尤穿鑿。</p><h3 id="象曰。比之無首。無所終也。" tabindex="-1">象曰。比之無首。無所終也。 <a class="header-anchor" href="#象曰。比之無首。無所終也。" aria-label="Permalink to “象曰。比之無首。無所終也。”">​</a></h3><p>道窮故無所終。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
